from lib import *
S = SS('j257')
steps = [
    step("System.exit(n) 的 n 在 shell 里只有 0–255:exit(0)、1、3、255 原样;exit(256) 是 0,exit(257) 是 1,exit(300) 是 44,exit(-1) 是 255,exit(-2) 是 254(对 256 取模)。异常的线程决定退出码:main 抛出未捕获异常 退出码 1;子线程抛出未捕获异常、main join 后正常结束 退出码 0;main 返回后 200 ms 非 daemon 子线程抛出 退出码 0;main 抛出异常而另一个非 daemon 线程还要跑 800 ms:等它正常结束后退出码 1。子线程的异常只打印堆栈,不改变退出码。", t=tl(S(1)), done=lidx(S(1), 'System.exit(0)', 'System.exit(255)', 'System.exit(256)', 'System.exit(300)'), mark=lidx(S(1), 'System.exit(-1)', 'main 抛出未捕获异常', '子线程抛出未捕获异常,main join', '稍后(200 ms)非 daemon', '另一个非 daemon 线程还要跑 800 ms'), kv=KV([['System.exit(256 / 257 / 300 / -1)', '0 / 1 / 44 / 255'], ['main 抛出未捕获异常', '退出码 1(等其它非 daemon 线程结束)'], ['子线程抛出未捕获异常', '退出码 0']], ['子线程抛出未捕获异常'])),
    step("两个线程同时调用 System.exit:一个 exit(1)、一个 exit(2),重复 30 次,退出码分布是 {1: 18, 2: 12}——每次只有一个调用生效,另一个被阻塞,谁先到由线程调度决定。程序的退出码在多个线程各自退出的设计里是不确定的。", t=tl(S(2)), done=lidx(S(2), '30 次的退出码分布'), mark=lidx(S(2), '30 次的退出码分布'), b=bars([['退出码 1', 18, '18 次'], ['退出码 2', 12, '12 次']], 30, done=[0, 1]), kv=KV([['30 次', '退出码 1 共 18 次,退出码 2 共 12 次']], ['30 次'])),
    step("OutOfMemoryError(-Xmx16m):默认下 main 不捕获时退出码 1(输出里还有 “OutOfMemoryError thrown from the UncaughtExceptionHandler”——打印异常本身也要分配内存);main 捕获后继续正常结束,退出码 0;子线程 OOM 之后 main 继续运行并正常结束,退出码 0。-XX:+ExitOnOutOfMemoryError:不论哪个线程 OOM,退出码都是 3(“Terminating due to java.lang.OutOfMemoryError: Java heap space”)。-XX:+CrashOnOutOfMemoryError:“Aborting due to …”,生成 68 KiB 的 hs_err 文件,退出码 1。-XX:OnOutOfMemoryError=\"echo …\" 会执行那条外部命令(“Executing \"echo 外部命令被执行了\"”),退出码 1。", t=tl(S(3)), done=lidx(S(3), '默认:main 里不捕获', '默认:main 捕获后继续', '默认:子线程 OOM 后 main 继续'), mark=lidx(S(3), '-XX:+ExitOnOutOfMemoryError', '-XX:+CrashOnOutOfMemoryError', '-XX:OnOutOfMemoryError'), kv=KV([['默认', '子线程 OOM 后进程继续,退出码 0'], ['ExitOnOutOfMemoryError', '退出码 3'], ['CrashOnOutOfMemoryError', 'hs_err 文件 68 KiB,退出码 1'], ['OnOutOfMemoryError', '执行外部命令']], ['ExitOnOutOfMemoryError'])),
    step("java 启动器自己的错误,退出码都是 1:主类不存在(Error: Could not find or load main class NoSuchMain)、主类存在但没有 main 方法(Error: Main method not found in class NoMain)、-Xmx0m(Invalid maximum heap size)、未知的 JVM 选项(Unrecognized VM option 'NoSuchFlag')、main 无限递归(StackOverflowError)。-version 是 0。启动失败与业务失败在退出码上无法区分——脚本需要靠输出,或在 main 里用自己的退出码约定。", t=tl(S(4)), done=lidx(S(4), '主类不存在', '主类存在但没有 main 方法'), mark=lidx(S(4), '无效的堆大小', '未知的 JVM 选项', '-version', '栈溢出'), kv=KV([['启动器错误 / StackOverflowError', '都是退出码 1'], ['-version', '退出码 0']], ['启动器错误 / StackOverflowError'])),
]
A = mkartj('j257', 257, 'Java,进程退出,退出码,System.exit,OutOfMemoryError,启动器,真实验证,动画演示',
    '在 JDK 21 上实测退出码:System.exit(256) 是 0、300 是 44、-1 是 255;子线程的未捕获异常不改变退出码;两个线程各 exit 的结果 18 / 12 随机;ExitOnOutOfMemoryError 的退出码是 3,默认 OOM 在子线程发生时进程继续并以 0 退出;java 启动器各类错误都是 1。',
    '进程退出码是调度器、脚本和 CI 判断“这次运行成功了吗”的唯一依据。这篇量出 JVM 在各种退出路径上给出的退出码,哪些异常不会改变它,以及 OOM 相关选项如何改变进程的命运。',
    [('300 → 44', 'System.exit(300) 在 shell 里看到的退出码(对 256 取模)'), ('0', '子线程抛出未捕获异常、main 正常结束时的退出码(只有 main 抛出才是 1)'), ('3', '-XX:+ExitOnOutOfMemoryError 触发时的退出码(默认不加这个选项时子线程 OOM 后进程以 0 退出)')],
    [('退出码的取值与异常线程', None), ('多线程同时 exit', None), ('OutOfMemoryError', None), ('启动器错误', None)],
    steps, [ENV_J + '。JDK 21.0.12;退出码由 Python subprocess 读取(信号终止为负值;本次实验里没有信号终止);OOM 实验用 -Xmx16m', '没有验证:Windows 的退出码范围、容器里 PID 1 的退出码传播、-XX:+ExitOnOutOfMemoryError 在 JDK 17 以前版本的行为、JVM 真正崩溃(SIGSEGV)时的退出码与 core 文件(CrashOnOutOfMemoryError 关闭了 core dump,所以这里观察到的是 1,不是 SIGABRT 的 134)'], 'JVM 进程退出状态')
